#!/usr/bin/env python3
from __future__ import annotations

import argparse
import difflib
import hashlib
import json
import re
from collections import Counter, defaultdict
from dataclasses import asdict, dataclass
from pathlib import Path

import pyarrow.parquet as pq

ROOT = Path("/tmp/cnm-train31")
SOURCE = ROOT / "source"
DATA = ROOT / "data"
SEED = "cnm-31-v1"
TARGETS = {"train": 210, "valid": 35, "test": 35}
ALLOWED_LICENSES = {
    "apache-2.0", "bsd-2-clause", "bsd-3-clause", "cc0-1.0", "isc", "mit", "unlicense"
}
STYLES = ("auto", "conventional", "angular", "google", "atom", "plain")
CONVENTIONAL = re.compile(
    r"^(?:build|chore|ci|docs|feat|fix|perf|refactor|revert|style|test)(?:\([^)]+\))?!?:\s*",
    re.I,
)
TRAILER = re.compile(r"^(?:signed-off-by|co-authored-by|bug-url|change-id|reviewed-by):", re.I)
WORDS = re.compile(r"[A-Za-z][A-Za-z0-9_-]{2,}")
STOP = {
    "add", "adds", "added", "change", "changes", "fix", "fixes", "fixed", "make", "makes",
    "remove", "removes", "removed", "update", "updates", "updated", "use", "uses", "with",
    "from", "into", "the", "and", "for", "this", "that", "when", "where", "support",
}


@dataclass
class Family:
    id: str
    source: str
    repo: str
    language: str
    license: str
    commit: str
    paths: list[str]
    diff: str
    subject: str
    body: str


def digest(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()


def clean_message(message: str) -> tuple[str, str]:
    lines = message.replace("\r\n", "\n").strip().splitlines()
    if not lines:
        return "", ""
    subject = CONVENTIONAL.sub("", lines[0].strip()).rstrip(".")
    body_lines = []
    for line in lines[1:]:
        if TRAILER.match(line.strip()) or "http://" in line or "https://" in line:
            continue
        body_lines.append(line.rstrip())
    body = "\n".join(body_lines).strip()
    body = re.sub(r"\n{3,}", "\n\n", body)
    return subject, body[:600]


def useful_subject(subject: str) -> bool:
    lowered = subject.lower().strip()
    return (
        10 <= len(subject) <= 47
        and not lowered.startswith(("merge ", "revert \"", "bump version"))
        and lowered not in {"update", "fix bug", "minor changes", "cleanup", "wip"}
        and not subject.endswith((":", ",", ";", "-"))
        and lowered.rsplit(" ", 1)[-1] not in {"a", "an", "and", "for", "from", "new", "of", "or", "the", "to", "unnecessary", "using", "via", "with"}
        and not re.search(r"https?://|#[0-9]{4,}", subject)
    )


def make_file_diff(old_path: str, new_path: str, old: str, new: str) -> str:
    old_name = old_path or new_path
    new_name = new_path or old_path
    lines = list(
        difflib.unified_diff(
            old.splitlines(keepends=True),
            new.splitlines(keepends=True),
            fromfile=f"a/{old_name}" if old else "/dev/null",
            tofile=f"b/{new_name}" if new else "/dev/null",
            n=3,
        )
    )
    if not lines:
        return ""
    return f"diff --git a/{old_name} b/{new_name}\n" + "".join(lines)


def contains_secret(diff: str) -> bool:
    patterns = (
        r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----",
        r"\bAKIA[0-9A-Z]{16}\b",
        r"(?i)://[^\s/:@]+:[^\s/@]+@[^\s/]+",
        r'''["'][^"'\s:]{1,32}:[^"'\s@]{6,}@[-A-Za-z0-9.]+(?::\d+)?["']''',
        r'''(?i)\b(?:api[_-]?key|access[_-]?token|secret[_-]?key|password)\s*[:=]\s*["'][^"']{12,}["']''',
    )
    return any(re.search(pattern, diff) for pattern in patterns)


