    text = (subject + " " + " ".join(paths)).lower()
    checks = (
        ("test", ("test", "spec")), ("docs", ("docs", "readme", "comment")),
        ("fix", ("fix", "bug", "crash", "error", "prevent", "correct")),
        ("refactor", ("refactor", "rename", "restructure", "cleanup")),
        ("perf", ("perf", "faster", "optimiz")), ("ci", ("workflow", ".github", " ci ")),
