def bullet_target(family: Family) -> str:
    if len(family.paths) < 2:
        raise ValueError("bullet target requires two changed files")
    first, second = (Path(path).name for path in family.paths[:2])
    return f"{family.subject}\n\n- Change {first}\n- Change {second}"


def needs_translation(index: int, variant: int) -> bool:
    return (variant == 0 and index % 5 == 0) or (variant == 3 and index % 5 == 1)


def make_records(split: str, families: list[Family], translations: dict[str, dict] | None) -> tuple[list[dict], list[dict]]:
    records, requested = [], []
    for index, family in enumerate(families):
        for variant in range(4):
            style = STYLES[(index * 3 + variant) % len(STYLES)] if variant < 3 else "custom"
            guidance = ""
            translated = None
            translation_id = f"{split}-{index}-{variant}"
            if needs_translation(index, variant):
                guidance = "Write the subject and any body in concise Simplified Chinese. Preserve required style prefixes such as Conventional Commit types."
                requested.append({"id": translation_id, "subject": family.subject, "body": family.body})
                if translations is not None:
                    item = translations[translation_id]
                    translated = (item["subject"], item.get("body", ""))
            if variant == 1 and not guidance:
                guidance = "Include the tracking reference #123 in a short body."
            elif variant == 2:
                guidance = "Keep the subject concise and do not include a body."

            if style == "custom":
                category = index % 5
                if category == 0:
                    guidance = "Start the subject with `SECURITY:` and add a body only when the diff supports one."
                    target = with_prefix("SECURITY: ", render("plain", family, include_body=bool(family.body)))
                elif category == 1:
                    target = render("plain", family, translated, include_body=False) if translated else ""
                elif category == 2 and len(family.paths) >= 2:
                    guidance = "Write an imperative subject, then one blank line, then exactly two concise bullet points naming two changed files."
                    target = bullet_target(family)
                elif category == 3 and family.body:
                    guidance = "Write a subject and a body whose first line starts with `Why:`."
                    target = f"{family.subject}\n\nWhy: {family.body}"
                else:
                    guidance = "Start the subject with `[CNM]` and do not include a body."
                    target = with_prefix("[CNM] ", family.subject)
            else:
                include_body = variant == 0
                target = render(style, family, translated, include_body=include_body) if (not needs_translation(index, variant) or translated) else ""
                if variant == 1:
                    base = render(style, family, include_body=False)
                    target = f"{base}\n\nTracking: #123"
                elif variant == 2:
                    target = render(style, family, include_body=False)

            records.append(
                {
                    "messages": prompt(style, family, guidance) + [{"role": "assistant", "content": target}],
                    "meta": {
                        "id": f"{family.id}:v{variant}", "family": family.id, "source": family.source,
                        "repo": family.repo, "language": family.language, "license": family.license,
                        "style": style, "guidance": guidance, "translation_id": translation_id if needs_translation(index, variant) else "",
                    },
                }
            )
    return records, requested


def write_jsonl(path: Path, rows: list[dict]) -> None:
    with path.open("w", encoding="utf-8") as stream:
        for row in rows:
            stream.write(json.dumps(row, ensure_ascii=False) + "\n")


def diff_lines(diff: str) -> set[str]:
    return {
        re.sub(r"\s+", " ", line[1:].strip().lower())
        for line in diff.splitlines()
        if line.startswith(("+", "-")) and not line.startswith(("+++", "---")) and len(line.strip()) > 8
    }


def max_eval_overlap(families: list[Family]) -> float:
    eval_rows = [json.loads(line) for line in (ROOT / "eval" / "high-risk.jsonl").read_text(encoding="utf-8").splitlines()]
    eval_sets = [diff_lines(row["user"].split("```diff\n", 1)[1].rsplit("\n```", 1)[0]) for row in eval_rows]
    maximum = 0.0
    for family in families:
        candidate = diff_lines(family.diff)
        for frozen in eval_sets:
            union = candidate | frozen
            if union:
                maximum = max(maximum, len(candidate & frozen) / len(union))
    return maximum


def prepare() -> None:
    DATA.mkdir(parents=True, exist_ok=True)
    candidates = load_commitpack() + load_lca()
    by_split = {name: balanced_pick([f for f in candidates if split_name(f.repo) == name], count) for name, count in TARGETS.items()}
    all_selected = [family for families in by_split.values() for family in families]
    if len({family.repo for family in all_selected}) != sum(len({f.repo for f in families}) for families in by_split.values()):
        raise RuntimeError("repository leakage across splits")
    if any(contains_secret(family.diff) for family in all_selected):
        raise RuntimeError("secret scan failed for selected families")
    overlap = max_eval_overlap(all_selected)
    if overlap >= 0.5:
        raise RuntimeError(f"training/eval near-duplicate overlap too high: {overlap:.3f}")
    write_jsonl(DATA / "families.jsonl", [{"split": split, **asdict(f)} for split, families in by_split.items() for f in families])
    requests = []
    for split, families in by_split.items():
        _, needed = make_records(split, families, None)
        requests.extend(needed)
    unique = {item["id"]: item for item in requests}
    (DATA / "translation-input.json").write_text(json.dumps(list(unique.values()), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    summary = {
        "source_candidates": len(candidates), "families": {k: len(v) for k, v in by_split.items()},
        "records": {k: len(v) * 4 for k, v in by_split.items()}, "translations": len(unique),
        "languages": Counter(f.language for f in all_selected), "sources": Counter(f.source for f in all_selected),
        "repos": {k: len({f.repo for f in v}) for k, v in by_split.items()}, "max_eval_jaccard": overlap,
    }
    (DATA / "prepare-summary.json").write_text(json.dumps(summary, default=dict, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(summary, default=dict, indent=2))


def finalize() -> None:
    translations = {item["id"]: item for item in json.loads((DATA / "translations.json").read_text(encoding="utf-8"))}
    rows = [json.loads(line) for line in (DATA / "families.jsonl").read_text(encoding="utf-8").splitlines()]
    families: dict[str, list[Family]] = defaultdict(list)
    for row in rows:
        split = row.pop("split")
        families[split].append(Family(**row))
    manifest = {"seed": SEED, "targets": TARGETS, "splits": {}}
    for split, items in families.items():
        records, _ = make_records(split, items, translations)
        if any(not row["messages"][-1]["content"].strip() for row in records):
            raise RuntimeError(f"empty target in {split}")
        path = DATA / f"{split}.jsonl"
        write_jsonl(path, records)
        manifest["splits"][split] = {
            "families": len(items), "records": len(records), "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "styles": Counter(row["meta"]["style"] for row in records),
            "languages": Counter(row["meta"]["language"] for row in records),
        }
    (DATA / "manifest.json").write_text(json.dumps(manifest, default=dict, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(manifest, default=dict, indent=2))


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("mode", choices=("prepare", "finalize"))
    args = parser.parse_args()
    prepare() if args.mode == "prepare" else finalize()


